import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"SmartScan Algorithm","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/smartscan-algorithm.md","filePath":"concepts/smartscan-algorithm.md","lastUpdated":null}'),i={name:"concepts/smartscan-algorithm.md"};function r(l,a,p,o,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="smartscan-algorithm" tabindex="-1">SmartScan Algorithm <a class="header-anchor" href="#smartscan-algorithm" aria-label="Permalink to &quot;SmartScan Algorithm&quot;">​</a></h1><p>SmartScan is a hybrid scheduler that <strong>learns on the job</strong>. It multiplexes five behaviours based on learned confidence.</p><h2 id="the-five-behaviours" tabindex="-1">The five behaviours <a class="header-anchor" href="#the-five-behaviours" aria-label="Permalink to &quot;The five behaviours&quot;">​</a></h2><h3 id="_1-reconnaissance-sweep" tabindex="-1">1. Reconnaissance sweep <a class="header-anchor" href="#_1-reconnaissance-sweep" aria-label="Permalink to &quot;1. Reconnaissance sweep&quot;">​</a></h3><p>Initial sweep across all bands to gather baseline statistics. Every band is visited at least <code>recon_factor × n_bands</code> times to build initial hit-rate estimates and detect any transmission activity.</p><h3 id="_2-cued-pursuit-phase-lock" tabindex="-1">2. Cued pursuit (phase-lock) <a class="header-anchor" href="#_2-cued-pursuit-phase-lock" aria-label="Permalink to &quot;2. Cued pursuit (phase-lock)&quot;">​</a></h3><p>When SmartScan detects a <strong>periodic</strong> emitter (one that transmits at regular intervals), it estimates the period using a Rayleigh estimator with integer refinement. Once validated (multiple consistent detections), it phase-locks and arrives <strong>before</strong> each predicted transmission window.</p><h3 id="_3-predict-and-probe" tabindex="-1">3. Predict-and-probe <a class="header-anchor" href="#_3-predict-and-probe" aria-label="Permalink to &quot;3. Predict-and-probe&quot;">​</a></h3><p>For phase-locked bands, SmartScan predicts the next ON window and positions the receiver there before it opens. This is the core intelligence advantage — being in the right place at the right time.</p><h3 id="_4-burst-characterisation" tabindex="-1">4. Burst characterisation <a class="header-anchor" href="#_4-burst-characterisation" aria-label="Permalink to &quot;4. Burst characterisation&quot;">​</a></h3><p>When a new or uncertain signal is detected, SmartScan allocates a short burst of consecutive dwells to characterise it: measure its frequency, pulse width, scan rhythm, and AOA. This builds the emitter fingerprint for identification.</p><h3 id="_5-value-weighted-rotation" tabindex="-1">5. Value-weighted rotation <a class="header-anchor" href="#_5-value-weighted-rotation" aria-label="Permalink to &quot;5. Value-weighted rotation&quot;">​</a></h3><p>After the recon phase, SmartScan allocates dwell time based on a value score:</p><ul><li><strong>High-value bands</strong> (recently productive, periodic locks, high SNR) get more time</li><li><strong>Cold bands</strong> (not visited recently) get guaranteed minimum visits (recency)</li><li><strong>Empty bands</strong> get progressively less time as confidence grows</li></ul><h2 id="decision-flow" tabindex="-1">Decision flow <a class="header-anchor" href="#decision-flow" aria-label="Permalink to &quot;Decision flow&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────┐</span></span>
<span class="line"><span>                    │   Band selected?     │</span></span>
<span class="line"><span>                    └──────────┬──────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                    ┌──────────▼──────────┐</span></span>
<span class="line"><span>                    │ Phase-locked on this │──YES──→ Cued pursuit</span></span>
<span class="line"><span>                    │ band?                │         (predict window)</span></span>
<span class="line"><span>                    └──────────┬──────────┘</span></span>
<span class="line"><span>                               │ NO</span></span>
<span class="line"><span>                    ┌──────────▼──────────┐</span></span>
<span class="line"><span>                    │ Persistent stream    │──YES──→ Value-weighted</span></span>
<span class="line"><span>                    │ confirmed?           │         exploitation</span></span>
<span class="line"><span>                    └──────────┬──────────┘</span></span>
<span class="line"><span>                               │ NO</span></span>
<span class="line"><span>                    ┌──────────▼──────────┐</span></span>
<span class="line"><span>                    │ Recon phase still    │──YES──→ Sequential sweep</span></span>
<span class="line"><span>                    │ active?              │</span></span>
<span class="line"><span>                    └──────────┬──────────┘</span></span>
<span class="line"><span>                               │ NO</span></span>
<span class="line"><span>                    ┌──────────▼──────────┐</span></span>
<span class="line"><span>                    │ Exploration needed   │──YES──→ Epsilon-greedy</span></span>
<span class="line"><span>                    │ (explore_eps)?       │         exploration</span></span>
<span class="line"><span>                    └──────────┬──────────┘</span></span>
<span class="line"><span>                               │ NO</span></span>
<span class="line"><span>                    ┌──────────▼──────────┐</span></span>
<span class="line"><span>                    │ Value-weighted       │</span></span>
<span class="line"><span>                    │ band selection       │</span></span>
<span class="line"><span>                    └─────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h2 id="key-parameters" tabindex="-1">Key parameters <a class="header-anchor" href="#key-parameters" aria-label="Permalink to &quot;Key parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>recon_factor</code></td><td>26</td><td>Recon slots per band = factor × n_bands</td></tr><tr><td><code>explore_eps</code></td><td>0.048</td><td>Post-recon random exploration rate</td></tr><tr><td><code>exploit_ramp</code></td><td>0.60</td><td>Steepness of exploitation ramp</td></tr><tr><td><code>recency_weight</code></td><td>0.16</td><td>Minimum revisit weight for cold bands</td></tr><tr><td><code>phase_lock_threshold</code></td><td>3</td><td>Consecutive validations needed for lock</td></tr><tr><td><code>persistent_window</code></td><td>10</td><td>Visits needed for persistent confirmation</td></tr><tr><td><code>persistent_threshold</code></td><td>0.85</td><td>Hit rate for persistent confirmation</td></tr></tbody></table><h2 id="predictions" tabindex="-1">Predictions <a class="header-anchor" href="#predictions" aria-label="Permalink to &quot;Predictions&quot;">​</a></h2><p>SmartScan makes binary predictions (ON/OFF) for the band it selects each slot:</p><ul><li><strong>ON</strong>: If the band has a validated phase-lock or is confirmed persistent</li><li><strong>OFF</strong>: Otherwise</li></ul><p>Prediction accuracy is evaluated over the steady-state phase (after initial reconnaissance) across all slots.</p>`,22)])])}const u=s(i,[["render",r]]);export{b as __pageData,u as default};
